from collections import Counter
def f(g):
    h,w=len(g),len(g[0])
    res=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            c=[g[i][j],g[i][w-1-j],g[h-1-i][j],g[h-1-i][w-1-j]]
            if len(set(c))>1:
                res[i][j]=Counter(c).most_common(1)[0][0]
    return res
