def vperiod(g):
    h=len(g); w=len(g[0])
    return next(p for p in range(1,h+1) if all(g[i][j]==g[i-p][j] for i in range(p,h) for j in range(w)))
def hperiod(g):
    h=len(g); w=len(g[0])
    return next(p for p in range(1,w+1) if all(g[i][j]==g[i][j-p] for i in range(h) for j in range(p,w)))
